// مهارة: data-processing & javascript-coding
// تنظيف وتوحيد البيانات الواردة من منصات متعددة
const items = $input.all();
const cleanedData = [];

for (const item of items) {
  const raw = item.json;

  // توحيد الحقول
  const clean = {
    platform: raw.platform || 'unknown',
    content_type: raw.type || 'post',
    text_content: (raw.text || raw.caption || '').trim(),
    author: raw.author || raw.username || 'anonymous',
    author_id: raw.author_id || raw.id || '',
    location: raw.location || raw.geo || '',
    timestamp: raw.timestamp || new Date().toISOString(),
    hashtags: Array.isArray(raw.hashtags) ? raw.hashtags : (raw.hashtags || '').split(',').map(t => t.trim()),
    engagement: {
      likes: parseInt(raw.likes) || 0,
      comments: parseInt(raw.comments) || 0,
      shares: parseInt(raw.shares) || 0
    },
    language: raw.language || 'auto-detect',
    raw_url: raw.url || ''
  };

  // فلترة أولية: استبعاد المحتوى غير ذي صلة تماماً
  const keywords = ['عمرة', 'حج', 'بدل', 'نيابة', 'متوفي', 'مريض', 'umrah', 'hajj', 'proxy', 'deceased'];
  const textLower = clean.text_content.toLowerCase();

  if (keywords.some(k => textLower.includes(k))) {
    cleanedData.push(clean);
  }
}

return cleanedData.map(d => ({ json: d }));

// مهارة: javascript-coding & contract-first
// دمج نتائج الذكاء الاصطناعي مع البيانات الأصلية وتطبيق نظام النقاط
const items = $input.all();
const results = [];

for (const item of items) {
  const original = item.json;
  const aiAnalysis = item.json.ai_analysis || {}; // نفترض أن العقدة السابقة أضافت هذا الحقل

  if (!aiAnalysis.is_potential_lead) continue; // تجاهل غير المؤهلين

  let score = parseInt(aiAnalysis.lead_score) || 0;

  // تعزيز النقاط بناءً على المعايير الشرعية
  if (aiAnalysis.relationship_guess === 'parent') score += 20;
  if (aiAnalysis.category === 'deceased' && aiAnalysis.urgency === 'high') score += 15;
  if (original.engagement.likes > 100) score += 5; // شعبية المنشور قد تدل على مصداقية

  // تحديد الأولوية
  let priority = 'normal';
  if (score >= 80) priority = 'critical';
  else if (score >= 60) priority = 'high';
  else if (score >= 40) priority = 'medium';

  results.push({
    json: {
      ...original,
      analysis: aiAnalysis,
      final_score: Math.min(score, 100),
      priority: priority,
      processed_at: new Date().toISOString(),
      status: 'new_lead'
    }
  });
}

// ترتيب حسب النقاط تنازلياً
return results.sort((a, b) => b.json.final_score - a.json.final_score);

